const readSheet = node({ type: 'n8n-nodes-base.googleSheets', version: 4.5, config: { "name": "Read Topic Sheet", "parameters": { "documentId": { "__rl": true, "mode": "id", "value": "1_RFLFLkxolbaSVOw-tWf8SuBKE0FV9n6dfqUrFoOA2k" }, "sheetName": { "__rl": true, "cachedResultName": "Sheet1", "mode": "list", "value": "gid=0" }, "options": {  } }, "retryOnFail": true, "maxTries": 4, "waitBetweenTries": 5000, "credentials": { "googleSheetsOAuth2Api": { "id": "0cZFMuAKCn5sTGLr", "name": "Google Sheets account" } } }, output: [{}] });
