const collect = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Collect Short IDs", "parameters": { "jsCode": "// 업로드된 쇼츠 중 아직 롱폼으로 만들지 않은 것의 유튜브 ID를 모은다 (최근 50개 — videos.list 1회 한도).\nconst rows = $('Read Topic Sheet').all().map(function (i) { return i.json; });\nconst log = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.ShortVideoId; });\nconst used = new Set(log.map(function (r) { return String(r.ShortVideoId).trim(); }));\nconst idOf = function (url) {\n  const m = String(url || '').match(/(?:v=|shorts\\/|youtu\\.be\\/)([A-Za-z0-9_-]{11})/);\n  return m ? m[1] : null;\n};\nconst seen = new Set();\nconst cands = [];\nrows.filter(function (r) { return String(r.Status || '').trim() === 'uploaded'; })\n  .sort(function (a, b) { return (b.row_number || 0) - (a.row_number || 0); })\n  .forEach(function (r) {\n    const id = idOf(r.VideoURL);\n    if (!id || used.has(id) || seen.has(id) || !/[가-힣]/.test(String(r.Topic || ''))) return;\n    seen.add(id);\n    cands.push({ id: id, topic: r.Topic, row: r.row_number });\n  });\nconst pick = cands.slice(0, 50);\nif (!pick.length) throw new Error('롱폼으로 만들 쇼츠가 없습니다 — 업로드된 한국어 쇼츠가 모두 이미 롱폼으로 만들어졌거나 VideoURL이 비어 있습니다');\nconsole.log('후보 쇼츠 ' + pick.length + '개 (이미 롱폼 ' + used.size + '개 제외)');\nreturn [{ json: { ids: pick.map(function (c) { return c.id; }).join(','), candidates: pick } }];\n" } }, output: [{}] });
const ytStats = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Shorts View Counts", "parameters": { "url": "https://www.googleapis.com/youtube/v3/videos", "authentication": "predefinedCredentialType", "nodeCredentialType": "youTubeOAuth2Api", "sendQuery": true, "queryParameters": { "parameters": [{ "name": "part", "value": "statistics,snippet" }, { "name": "id", "value": expr("{{ $json.ids }}") }, { "name": "maxResults", "value": "50" }] }, "options": { "timeout": 60000 } }, "retryOnFail": true, "maxTries": 3, "waitBetweenTries": 5000, "credentials": { "youTubeOAuth2Api": { "id": "HE5xUScbPHMgviXV", "name": "YouTube account" } } }, output: [{}] });
const pickShort = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Pick Short", "parameters": { "jsCode": "// 조회수가 가장 높은 쇼츠를 롱폼 주제로 고른다.\nconst c = $('Collect Short IDs').first().json;\nconst stats = {};\n($input.first().json.items || []).forEach(function (v) {\n  const s = v.statistics || {};\n  stats[v.id] = { views: Number(s.viewCount || 0), likes: Number(s.likeCount || 0), title: (v.snippet && v.snippet.title) || '' };\n});\nconst ranked = c.candidates\n  .filter(function (x) { return stats[x.id]; })\n  .map(function (x) { return Object.assign({}, x, stats[x.id]); })\n  .sort(function (a, b) { return b.views - a.views; });\nif (!ranked.length) throw new Error('유튜브 조회수를 가져오지 못했습니다 (영상 ' + c.candidates.length + '개 모두 조회 실패) — YouTube 크리덴셜/할당량 확인');\nconst top = ranked[0];\nconsole.log('조회수 순위: ' + ranked.slice(0, 5).map(function (x) { return x.views + '회 ' + String(x.title).slice(0, 30); }).join(' | '));\nreturn [{ json: { Topic: top.topic, Language: 'Korean', shortVideoId: top.id, shortViews: top.views, shortTitle: top.title, row_number: top.row } }];\n" } }, output: [{}] });
const buildReq = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Build Longform Request", "parameters": { "jsCode": "// ===== 설정 =====\nconst MAX_IMAGES = 14;          // 영상 한 편 AI 이미지 장면 최대 개수 (+ 썸네일 1장)\nconst TARGET_KO = [3400, 4000]; // 한국어 나레이션 글자 수 (공백 포함) ≈ 8~9.5분\nconst TARGET_EN = [1350, 1600]; // 영어 단어 수\n// ================\n\nconst topic = $json.Topic;\nconst language = $json.Language || 'Korean';\nconst isKorean = String(language).trim().toLowerCase() === 'korean';\nconst lengthRule = isKorean\n  ? `The full narration (all scenes together) must be between ${TARGET_KO[0]} and ${TARGET_KO[1]} Korean characters including spaces (8 to 9.5 minutes spoken). This is a hard rule: count as you go. Under ${TARGET_KO[0]} is a failure.`\n  : `The full narration (all scenes together) must be between ${TARGET_EN[0]} and ${TARGET_EN[1]} English words (8 to 9.5 minutes spoken). Under ${TARGET_EN[0]} is a failure.`;\n\nconst prompt = `You are the scriptwriter AND motion designer for NextYou Global, a YouTube channel covering Bible devotionals, life wisdom, psychology, health science and money. One of our Shorts did well, and you are turning its topic into an 8 to 10 minute long-form video (16:9) that goes far deeper than the Short could.\n\nSource Short topic: ${topic}\nShort title on YouTube: ${$json.shortTitle || ''} (${$json.shortViews || 0} views)\nLanguage: ${language}. Write everything viewers see or hear in ${language}.\n\n=== LENGTH (hard rule) ===\n${lengthRule}\nEarn the length with substance: concrete scenes, real examples, mechanisms, counter-arguments, a practical method. Never pad, never restate a point you already made.\n\n=== STRUCTURE ===\n5 to 7 chapters, in order:\n1. HOOK (30 to 45 seconds): open mid-tension with the most surprising claim or scene, then promise exactly what the viewer will walk away with. No greeting, no channel intro. BANNED openings: 안녕하세요, 여러분, 오늘은 ~에 대해, 지금 마음이 힘드신가요, Hello everyone, In this video.\n2. Body chapters (3 to 5): each answers one question the viewer would ask next. Each opens with a fresh mini-hook, contains at least one concrete example (a person, a scene, a number, a study or a passage), and ends with a one-line takeaway that pulls into the next chapter (an open loop).\n3. CLOSING chapter: recap the 3 key points in one breath each, give one action small enough to do today, then ask viewers one specific question to answer in the comments, then a natural subscribe line.\nChapter titles: max 18 Korean characters / 6 English words, plain and searchable (these become YouTube chapters).\n\n=== CONTENT RULES BY TYPE ===\n- If the topic is a Bible passage or faith theme: sermon-style. Quote scripture accurately (Korean: 개역개정 wording) with the reference, warm 합니다 register, bring in the biblical person and context, no psychology studies or secular figures, end with a short prayer line and 아멘. Never invent or paraphrase a verse and call it scripture.\n- Wisdom / psychology: only quotes that are genuinely and widely attributed; never claim a person followed a philosophy unless well documented. Name studies only if you are sure they exist; otherwise describe the finding generally.\n- Health: evidence-based and general, no medical advice, no dosages, add one line that people with conditions should talk to their doctor.\n- Money / economy: financial literacy, not advice. Never name a stock, coin, fund or product to buy, never promise returns or predict markets. Use standard checkable math (compound interest, rule of 72, inflation).\n\n=== SCENES (motion design) ===\nSplit each chapter into 8 to 14 scenes. Each scene = { \"narration\": the exact words spoken (one or two sentences, about 40 to 80 Korean characters), \"visual\": what is on screen }. Narration is spoken text only: no stage directions, emoji or brackets. Joining all narrations in order must give the complete script.\nThe narration already appears as captions, so on-screen text must NOT repeat it: pull out the key phrase, number or contrast.\n\nVisual types (use ONLY these):\n- chapter: {\"type\":\"chapter\",\"title\":\"chapter title\",\"number\":2} - REQUIRED as the visual of the FIRST scene of every chapter except chapter 1. Its narration is the chapter's opening line.\n- headline: {\"type\":\"headline\",\"text\":\"key phrase, max 18 Korean chars / 7 English words\",\"highlight\":[\"1-2 words from text\"],\"emoji\":\"optional single emoji\"}\n- stat: {\"type\":\"stat\",\"label\":\"max 16 chars\",\"value\":number,\"prefix\":\"optional\",\"suffix\":\"unit\",\"decimals\":0,\"sub\":\"assumption or source, max 24 chars\"} - only real numbers that the narration says.\n- chart: {\"type\":\"chart\",\"title\":\"max 18 chars\",\"unit\":\"shared unit\",\"items\":[{\"label\":\"max 6 chars\",\"value\":number}]} - 2 to 4 bars, labels spoken in the narration.\n- list: {\"type\":\"list\",\"title\":\"max 16 chars\",\"items\":[\"2 to 4 items, max 12 Korean chars each\"]}\n- compare: {\"type\":\"compare\",\"title\":\"max 16 chars\",\"left\":{\"label\":\"the common/wrong side\",\"text\":\"max 16 chars\"},\"right\":{\"label\":\"the better side\",\"text\":\"max 16 chars\"}}\n- quote: {\"type\":\"quote\",\"text\":\"max 40 chars\",\"author\":\"name\"} - real quotes only.\n- scripture: {\"type\":\"scripture\",\"text\":\"verse wording, max 60 chars\",\"author\":\"reference e.g. 이사야 41:10\"} - sermon only.\n- icon: {\"type\":\"icon\",\"emoji\":\"one emoji\",\"text\":\"max 14 chars\"}\n- image: {\"type\":\"image\",\"prompt\":\"English image prompt, under 30 words\",\"text\":\"optional overlay keyword, max 12 Korean chars\",\"highlight\":[\"word from text\"]} - a full-screen 16:9 AI illustration. Use for up to ${MAX_IMAGES} scenes spread across all chapters (a concrete moment, place or object), never two in a row, never for numbers or lists. Prompt rules: describe only the CONTENT (style is added automatically); give time of day, weather and light; at most one person, written as an adult figure with no age, gender, nationality or ethnicity; never children; modest clothing; never a real identifiable person; no text or logos; no religious icons of specific figures.\n- outro: {\"type\":\"outro\",\"text\":\"closing line, max 16 chars\",\"highlight\":[\"word\"],\"cta\":\"short subscribe call\"} - ONLY the very last scene.\n\nDesign rules: never the same type twice in a row (except image never twice in a row either). Each body chapter uses at least 3 different types. Numbers on screen must exactly match the narration; never invent numbers. SERMON: no stat or chart. highlight words must literally appear in that scene's text. Never use the straight double-quote character inside any value; use “ ” or 「 」.\n\n=== SEO & THUMBNAIL ===\ntitle: under 60 characters, the searchable keyword first, a curiosity gap, honest. Include the scripture reference for sermons. Must differ from the Short's title.\ndescription: 3 to 5 short lines on what the video answers and who it is for (no timestamps - they are added automatically), then the channel line (Korean: 📌 Next You Global 채널은 성경 말씀, 지혜, 심리, 건강, 돈 이야기를 깊이 있게 전합니다.) and a subscribe line (👉 구독 & 좋아요로 함께 성장해요!).\ntags: 10 to 15 search tags without #, specific first.\nhashtags: exactly 3, the last is #NextYouGlobal.\nthumbnail: {\"text\":\"6 to 14 Korean characters, a punchy promise that complements the title (not a copy)\",\"highlight\":[\"one word from text\"],\"badge\":\"very short label e.g. 10분 정리 / 말씀 묵상 / 꼭 알아야 할 3가지\",\"prompt\":\"English image prompt for the thumbnail picture: one striking subject on the RIGHT half, simple darker background on the left for text, same safety rules as image scenes\"}\ncategory: EXACTLY ONE of bible, quote, wealth, health, other.\nmood: EXACTLY ONE of calm_reflective, hopeful_uplifting, tense_dramatic, dark_serious, warm_gentle.\n\nRespond ONLY with valid JSON, no markdown fences, first character the opening brace:\n{\"title\":\"...\",\"description\":\"...\",\"tags\":[\"...\"],\"hashtags\":[\"#...\"],\"category\":\"...\",\"mood\":\"...\",\"thumbnail\":{\"text\":\"...\",\"highlight\":[\"...\"],\"badge\":\"...\",\"prompt\":\"...\"},\"chapters\":[{\"title\":\"...\",\"scenes\":[{\"narration\":\"...\",\"visual\":{\"type\":\"headline\",\"text\":\"...\",\"highlight\":[\"...\"]}}]}]}`;\n\nconsole.log('롱폼 주제: ' + topic + ' (쇼츠 조회 ' + ($json.shortViews || 0) + ')');\nreturn [{ json: {\n  body: { model: 'claude-sonnet-4-6', max_tokens: 24000, messages: [{ role: 'user', content: prompt }] },\n  Topic: topic, Language: language, shortVideoId: $json.shortVideoId, shortViews: $json.shortViews, maxImages: MAX_IMAGES\n} }];\n" } }, output: [{}] });
const claude = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Claude - Longform Script", "parameters": { "method": "POST", "url": "https://api.anthropic.com/v1/messages", "authentication": "predefinedCredentialType", "nodeCredentialType": "anthropicApi", "sendHeaders": true, "headerParameters": { "parameters": [{ "name": "anthropic-version", "value": "2023-06-01" }, { "name": "content-type", "value": "application/json" }] }, "sendBody": true, "specifyBody": "json", "jsonBody": expr("{{ $json.body }}"), "options": { "timeout": 600000 } }, "retryOnFail": true, "maxTries": 2, "waitBetweenTries": 10000, "credentials": { "anthropicApi": { "id": "AsWnrNE2knZqRLta", "name": "Anthropic account" } } }, output: [{}] });
const parse = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Parse Longform Script", "parameters": { "jsCode": "// Claude 롱폼 대본(JSON)을 검증하고 장면을 한 줄로 펼친다 (장면마다 chapter 번호).\nconst raw = String($json.content && $json.content[0] && $json.content[0].text || '');\nconst stop = $json.stop_reason || '';\nlet clean = raw.replace(/```json|```/g, '').trim();\nconst tryParse = t => { try { return JSON.parse(t); } catch (e) { return null; } };\nconst sliceBraces = t => { const s = t.indexOf('{'), e = t.lastIndexOf('}'); return (s !== -1 && e > s) ? t.slice(s, e + 1) : t; };\nlet parsed = tryParse(clean);\nif (typeof parsed === 'string') parsed = tryParse(parsed);\nif (!parsed) parsed = tryParse(sliceBraces(clean));\nif (!parsed) {\n  const fixed = sliceBraces(clean).replace(/([^\\s{\\[,:])\"([^\\s,}\\]:])/g, '$1”$2');\n  parsed = tryParse(fixed);\n}\nif (!parsed) throw new Error('Claude 롱폼 JSON 파싱 실패' + (stop === 'max_tokens' ? ' (응답이 max_tokens에서 잘림)' : '') + ' — 앞 300자: ' + clean.slice(0, 300));\n\nconst src = $('Build Longform Request').first().json;\nconst subtitleLang = String(src.Language || 'Korean').trim().toLowerCase() === 'english' ? 'en' : 'ko';\nconst maxImages = Number(src.maxImages) || 14;\nconst s = v => String(v == null ? '' : v).replace(/[\"]/g, '”').trim();\n\nconst chaptersIn = (Array.isArray(parsed.chapters) ? parsed.chapters : []).filter(c => c && Array.isArray(c.scenes) && c.scenes.length);\nif (chaptersIn.length < 3) throw new Error('챕터가 너무 적습니다: ' + chaptersIn.length + '개');\n\nconst chapters = [];\nconst scenes = [];\nchaptersIn.forEach((c, ci) => {\n  const title = s(c.title).slice(0, 40) || ('Part ' + (ci + 1));\n  chapters.push({ title });\n  c.scenes.forEach((sc, si) => {\n    const narration = s(sc && sc.narration).replace(/\\s*\\n\\s*/g, ' ');\n    if (!narration) return;\n    let visual = sc && typeof sc.visual === 'object' && sc.visual ? sc.visual : { type: 'headline', text: narration.slice(0, 18) };\n    // 챕터 첫 장면은 챕터 표지 (1장 제외), 그 밖의 chapter 타입은 headline으로\n    if (si === 0 && ci > 0) visual = { type: 'chapter', title, number: ci + 1, highlight: [] };\n    else if (visual.type === 'chapter') visual = { type: 'headline', text: s(visual.title || visual.text || narration.slice(0, 18)) };\n    scenes.push({ narration, visual, chapter: ci });\n  });\n});\nif (scenes.length < 30) throw new Error('장면이 너무 적습니다: ' + scenes.length + '개');\nif (scenes.length > 140) scenes.splice(140);\n\nconst MOODS = ['calm_reflective', 'hopeful_uplifting', 'tense_dramatic', 'dark_serious', 'warm_gentle'];\nconst CATEGORIES = ['bible', 'quote', 'wealth', 'health', 'other'];\nconst script = scenes.map(x => x.narration).join('\\n');\nconst isSermon = /아멘|Amen/.test(script.slice(-400)) || String(parsed.category) === 'bible';\nlet category = String(parsed.category || '').trim().toLowerCase();\nif (!CATEGORIES.includes(category)) category = isSermon ? 'bible' : 'other';\nconst mood = MOODS.includes(parsed.mood) ? parsed.mood : 'calm_reflective';\n\n// 이미지 장면: 개수 상한, 연속 금지, 프롬프트 너무 짧으면 headline\nlet imageCount = 0, prevImage = false;\nfor (const x of scenes) {\n  const v = x.visual;\n  if (v.type !== 'image') { prevImage = false; continue; }\n  const ok = String(v.prompt || '').replace(/[^a-z]/gi, '').length >= 15;\n  if (ok && !prevImage && imageCount < maxImages) { imageCount++; prevImage = true; continue; }\n  x.visual = { type: 'headline', text: s(v.text || x.narration.slice(0, 18)), highlight: v.highlight || [] };\n  prevImage = false;\n}\nif (isSermon) for (const x of scenes) if (x.visual.type === 'stat' || x.visual.type === 'chart') x.visual = { type: 'headline', text: x.narration.slice(0, 18), highlight: [] };\n// 마지막 장면만 outro\nscenes.forEach((x, i) => { if (x.visual.type === 'outro' && i !== scenes.length - 1) x.visual = { type: 'headline', text: s(x.visual.text), highlight: x.visual.highlight || [] }; });\n\nconst len = subtitleLang === 'en' ? script.split(/\\s+/).length : script.length;\nconst [lo, hi] = subtitleLang === 'en' ? [1000, 2200] : [2400, 5500];\nif (len < lo) throw new Error('대본이 너무 짧습니다: ' + len + (subtitleLang === 'en' ? '단어' : '자') + ' (최소 ' + lo + ') — 다시 실행하세요');\nif (len > hi) throw new Error('대본이 너무 깁니다: ' + len + (subtitleLang === 'en' ? '단어' : '자') + ' (최대 ' + hi + ')');\nconst warnings = [];\nif (subtitleLang === 'ko' && len < 3200) warnings.push('대본 ' + len + '자 — 목표(3,400자)보다 짧아 8분이 안 될 수 있음');\n\nconst th = parsed.thumbnail || {};\nconst thumbnail = { text: s(th.text).slice(0, 24) || s(parsed.title).slice(0, 20), highlight: (Array.isArray(th.highlight) ? th.highlight : []).map(s).slice(0, 2), badge: s(th.badge).slice(0, 14), prompt: s(th.prompt) };\nconst hashtags = (Array.isArray(parsed.hashtags) ? parsed.hashtags : []).map(s).filter(h => h.startsWith('#')).slice(0, 3);\nconst tags = (Array.isArray(parsed.tags) ? parsed.tags : []).map(t => s(t).replace(/^#/, '')).filter(Boolean);\nlet tagStr = '';\nfor (const t of tags) { if ((tagStr + ',' + t).length > 450) break; tagStr = tagStr ? tagStr + ',' + t : t; }\n\nconsole.log('chars: ' + len + ' | chapters: ' + chapters.length + ' | scenes: ' + scenes.length + ' | images: ' + imageCount + ' | ' + category + '/' + mood + (warnings.length ? ' | ' + warnings.join(' ') : ''));\nreturn [{ json: {\n  title: s(parsed.title || src.Topic).slice(0, 100),\n  description: s(parsed.description),\n  hashtags, tagStr, script, scenes, chapters, thumbnail,\n  category, mood, imageCount, format: isSermon ? 'sermon' : 'essay',\n  scriptLength: len, warnings,\n  topic: src.Topic, language: src.Language || 'Korean', subtitleLang,\n  shortVideoId: src.shortVideoId, shortViews: src.shortViews\n} }];\n" } }, output: [{}] });
const tts = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "ElevenLabs TTS (timestamps)", "parameters": { "method": "POST", "url": expr("https://api.elevenlabs.io/v1/text-to-speech/{{ $json.subtitleLang === 'ko' ? 'srhGhMYcxqeTNVuSRvWg' : 'CwhRBWXzGAHq8TQ4Fs17' }}/with-timestamps"), "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "sendHeaders": true, "headerParameters": { "parameters": [{ "name": "content-type", "value": "application/json" }] }, "sendBody": true, "specifyBody": "json", "jsonBody": expr("{{ { \"text\": $json.script, \"model_id\": \"eleven_multilingual_v2\", \"voice_settings\": { \"stability\": 0.5, \"similarity_boost\": 0.75, \"speed\": 1.08 } } }}"), "options": { "timeout": 480000 } }, "retryOnFail": true, "maxTries": 2, "waitBetweenTries": 10000, "credentials": { "httpHeaderAuth": { "id": "tttbA9a5I55qIbLc", "name": "ElevenLabs API" } } }, output: [{}] });
