const tgApproval = node({ type: 'n8n-nodes-base.telegram', version: 1.2, config: { "name": "Telegram Approval", "parameters": { "operation": "sendAndWait", "chatId": "6213393108", "message": expr("🎬 롱폼 렌더 완료\n\n제목: {{ $('Parse Longform Script').first().json.title }}\n원본 쇼츠: {{ $('Pick Short').first().json.shortTitle }} (조회 {{ $('Pick Short').first().json.shortViews }})\n길이: {{ $('Check Render Result').first().json.durationText }} · 챕터 {{ $('Parse Longform Script').first().json.chapters.length }}개 · 장면 {{ $('Build Render Job').first().json.sceneCount }}개\n대본: {{ $('Parse Longform Script').first().json.scriptLength }}자 · 카테고리 {{ $('Parse Longform Script').first().json.category }}\nAI 이미지: {{ $('Build Render Job').first().json.imagesOk }}장 (실패 {{ $('Build Render Job').first().json.imagesFailed }}) · 썸네일 이미지 {{ $('Build Render Job').first().json.thumbImage ? '있음' : '없음' }}\n렌더: {{ Math.round($('Check Render Result').first().json.render_sec / 60) }}분 · {{ $('Check Render Result').first().json.size_mb }}MB\n경고: {{ $('Check Render Result').first().json.warningsText }}\n\n미리보기: https://drive.google.com/file/d/{{ $json.id }}/view\n\n업로드할까요? (거절하면 이 쇼츠는 다음에 다시 고르지 않습니다)"), "options": {  } }, "credentials": { "telegramApi": { "id": "MqKwiZpa0oSigPGM", "name": "Telegram account" } } }, output: [{}] });
