const uploadMeta = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Build Upload Meta", "parameters": { "jsCode": "// 업로드할 설명란: Claude 설명 + 렌더 결과의 챕터 시각(유튜브 챕터) + 원본 쇼츠 링크 + 해시태그\nconst p = $('Parse Longform Script').first().json;\nconst r = $('Check Render Result').first().json;\nconst fmt = function (sec) {\n  sec = Math.max(0, Math.floor(sec));\n  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;\n  const pad = function (n) { return String(n).padStart(2, '0'); };\n  return h ? h + ':' + pad(m) + ':' + pad(s) : pad(m) + ':' + pad(s);\n};\n// 유튜브 챕터 조건: 00:00 시작, 3개 이상, 각 10초 이상\nlet chapters = (r.chapters || []).filter(function (c) { return c && c.title && Number.isFinite(Number(c.start)); });\nchapters = chapters.filter(function (c, i) { return i === 0 || Number(c.start) - Number(chapters[i - 1].start) >= 10; });\nlet chapterBlock = '';\nif (chapters.length >= 3) {\n  chapters[0].start = 0;\n  chapterBlock = '\\n\\n⏱ 목차\\n' + chapters.map(function (c) { return fmt(c.start) + ' ' + c.title; }).join('\\n');\n}\nconst shortLine = p.shortVideoId ? '\\n\\n▶ 이 영상의 60초 쇼츠: https://youtube.com/shorts/' + p.shortVideoId : '';\nconst description = (p.description + chapterBlock + shortLine + '\\n\\n' + (p.hashtags || []).join(' ')).slice(0, 4900);\nconsole.log('챕터 ' + chapters.length + '개 | 설명 ' + description.length + '자');\nreturn [{ json: { title: p.title, description: description, tags: p.tagStr, chapterCount: chapters.length } }];\n" } }, output: [{}] });
const dlFinal = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Download Video for Upload", "parameters": { "url": expr("https://api.github.com/repos/{{ $('Check Render Result').first().json.repo }}/releases/assets/{{ $('Check Render Result').first().json.asset_id }}"), "authentication": "predefinedCredentialType", "nodeCredentialType": "githubApi", "sendHeaders": true, "headerParameters": { "parameters": [{ "name": "Accept", "value": "application/octet-stream" }] }, "options": { "response": { "response": { "responseFormat": "file" } }, "timeout": 300000 } }, "retryOnFail": true, "maxTries": 3, "waitBetweenTries": 5000, "credentials": { "githubApi": { "id": "a2UFvOs5ceHM8VC5", "name": "GitHub account" } } }, output: [{}] });
const ytUpload = node({ type: 'n8n-nodes-base.youTube', version: 1, config: { "name": "YouTube Upload", "parameters": { "resource": "video", "operation": "upload", "title": expr("{{ $('Build Upload Meta').first().json.title }}"), "regionCode": "CA", "categoryId": "27", "options": { "description": expr("{{ $('Build Upload Meta').first().json.description }}"), "privacyStatus": "public", "tags": expr("{{ $('Build Upload Meta').first().json.tags }}") } }, "retryOnFail": true, "maxTries": 3, "waitBetweenTries": 5000, "credentials": { "youTubeOAuth2Api": { "id": "HE5xUScbPHMgviXV", "name": "YouTube account" } } }, output: [{}] });
const dlThumb = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Download Thumbnail", "parameters": { "url": expr("https://api.github.com/repos/{{ $('Check Render Result').first().json.repo }}/releases/assets/{{ $('Check Render Result').first().json.thumb_asset_id || 'none' }}"), "authentication": "predefinedCredentialType", "nodeCredentialType": "githubApi", "sendHeaders": true, "headerParameters": { "parameters": [{ "name": "Accept", "value": "application/octet-stream" }] }, "options": { "response": { "response": { "responseFormat": "file" } }, "timeout": 300000 } }, "retryOnFail": true, "maxTries": 2, "waitBetweenTries": 5000, "onError": "continueRegularOutput", "credentials": { "githubApi": { "id": "a2UFvOs5ceHM8VC5", "name": "GitHub account" } } }, output: [{}] });
const setThumb = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Set Thumbnail", "parameters": { "method": "POST", "url": expr("https://www.googleapis.com/upload/youtube/v3/thumbnails/set?videoId={{ $('YouTube Upload').first().json.uploadId }}"), "authentication": "predefinedCredentialType", "nodeCredentialType": "youTubeOAuth2Api", "sendBody": true, "contentType": "binaryData", "inputDataFieldName": "data", "options": { "timeout": 60000 } }, "onError": "continueRegularOutput", "credentials": { "youTubeOAuth2Api": { "id": "HE5xUScbPHMgviXV", "name": "YouTube account" } } }, output: [{}] });
const logRow = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Log Row (uploaded)", "parameters": { "jsCode": "// MotionLongform 탭에 남길 한 줄. STATUS는 노드마다 다르다 (uploaded / rejected).\nconst STATUS = 'uploaded';\nconst p = $('Parse Longform Script').first().json;\nconst r = $('Check Render Result').first().json;\nlet url = '';\ntry { url = 'https://youtube.com/watch?v=' + $('YouTube Upload').first().json.uploadId; } catch (e) { /* 거절된 경우 */ }\nreturn [{ json: {\n  Date: $now.toFormat('yyyy-MM-dd HH:mm'), ShortTopic: p.topic, ShortVideoId: p.shortVideoId, ShortViews: p.shortViews,\n  LongTitle: p.title, Status: STATUS, LongURL: STATUS === 'uploaded' ? url : '', JobId: r.jobId\n} }];\n" } }, output: [{}] });
const appendLog = node({ type: 'n8n-nodes-base.googleSheets', version: 4.5, config: { "name": "Append Longform Log", "parameters": { "operation": "append", "documentId": { "__rl": true, "mode": "id", "value": "1_RFLFLkxolbaSVOw-tWf8SuBKE0FV9n6dfqUrFoOA2k" }, "sheetName": { "__rl": true, "mode": "name", "value": "MotionLongform" }, "columns": { "mappingMode": "autoMapInputData", "value": {  } }, "options": {  } }, "retryOnFail": true, "maxTries": 4, "waitBetweenTries": 5000, "credentials": { "googleSheetsOAuth2Api": { "id": "0cZFMuAKCn5sTGLr", "name": "Google Sheets account" } } }, output: [{}] });
const notifyDone = node({ type: 'n8n-nodes-base.telegram', version: 1.2, config: { "name": "Notify Upload Complete", "parameters": { "chatId": "6213393108", "additionalFields": {  }, "text": expr("✅ 롱폼 업로드 완료\n\n제목: {{ $('Build Upload Meta').first().json.title }}\n챕터: {{ $('Build Upload Meta').first().json.chapterCount }}개 · 썸네일: {{ $('Set Thumbnail').first().json.error ? '실패 (유튜브 채널 인증 필요할 수 있음)' : '적용' }}\n\n링크: https://youtube.com/watch?v={{ $('YouTube Upload').first().json.uploadId }}") }, "credentials": { "telegramApi": { "id": "MqKwiZpa0oSigPGM", "name": "Telegram account" } } }, output: [{}] });
const findPlaylists = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Find Playlists", "parameters": { "url": "https://www.googleapis.com/youtube/v3/playlists", "authentication": "predefinedCredentialType", "nodeCredentialType": "youTubeOAuth2Api", "sendQuery": true, "queryParameters": { "parameters": [{ "name": "part", "value": "snippet" }, { "name": "mine", "value": "true" }, { "name": "maxResults", "value": "50" }] }, "options": { "timeout": 30000 } }, "onError": "continueRegularOutput", "credentials": { "youTubeOAuth2Api": { "id": "HE5xUScbPHMgviXV", "name": "YouTube account" } } }, output: [{}] });
const pickPlaylist = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Pick Playlist", "parameters": { "jsCode": "// 롱폼은 재생목록 하나에 모은다. 제목이 정확히 같은 재생목록이 있으면 거기에 추가하고, 없으면 새로 만든다.\nconst p = $('Parse Longform Script').first().json;\nconst target = { title: 'NextYou Global 롱폼 | 깊이 보기', description: '쇼츠에서 반응이 좋았던 주제를 8~10분으로 깊이 풀어낸 영상 모음' };\nconst res = $input.first().json || {};\n\n// 조회가 실패했는데 새로 만들면 같은 재생목록이 매번 하나씩 생긴다. 그럴 땐 건너뛴다.\nif (res.error || !Array.isArray(res.items)) {\n  console.log('재생목록 조회 실패 — 이번엔 건너뜀 (중복 생성 방지): ' + JSON.stringify(res.error || res).slice(0, 200));\n  return [];\n}\n\nconst norm = function (s) { return String(s || '').replace(/\\s+/g, ' ').trim(); };\nconst found = res.items.find(function (it) { return norm(it.snippet && it.snippet.title) === norm(target.title); });\nconsole.log((found ? '기존 재생목록에 추가: ' : '새 재생목록 생성: ') + target.title + ' (category: ' + p.category + ')');\n\nreturn [{ json: { playlistId: found ? found.id : '', title: target.title, description: target.description } }];\n" } }, output: [{}] });
const plExists = ifElse({ version: 2.2, config: { "name": "Playlist Exists?", "parameters": { "conditions": { "options": { "caseSensitive": true, "leftValue": "", "typeValidation": "loose", "version": 2 }, "conditions": [{ "leftValue": expr("{{ $json.playlistId }}"), "operator": { "operation": "notEmpty", "singleValue": true, "type": "string" }, "rightValue": "" }], "combinator": "and" }, "options": {  } } } });
const createPlaylist = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Create Playlist", "parameters": { "method": "POST", "url": "https://www.googleapis.com/youtube/v3/playlists", "authentication": "predefinedCredentialType", "nodeCredentialType": "youTubeOAuth2Api", "sendQuery": true, "queryParameters": { "parameters": [{ "name": "part", "value": "snippet,status" }] }, "sendBody": true, "specifyBody": "json", "jsonBody": expr("{{ { snippet: { title: $json.title, description: $json.description, defaultLanguage: 'ko' }, status: { privacyStatus: 'public' } } }}"), "options": { "timeout": 30000 } }, "retryOnFail": true, "maxTries": 2, "waitBetweenTries": 5000, "credentials": { "youTubeOAuth2Api": { "id": "HE5xUScbPHMgviXV", "name": "YouTube account" } } }, output: [{}] });
const addToPlaylist = node({ type: 'n8n-nodes-base.httpRequest', version: 4.3, config: { "name": "Add To Playlist", "parameters": { "method": "POST", "url": "https://www.googleapis.com/youtube/v3/playlistItems", "authentication": "predefinedCredentialType", "nodeCredentialType": "youTubeOAuth2Api", "sendQuery": true, "queryParameters": { "parameters": [{ "name": "part", "value": "snippet" }] }, "sendBody": true, "specifyBody": "json", "jsonBody": expr("{{ { snippet: { playlistId: $json.playlistId || $json.id, resourceId: { kind: 'youtube#video', videoId: $('YouTube Upload').first().json.uploadId } } } }}"), "options": { "timeout": 30000 } }, "retryOnFail": true, "maxTries": 3, "waitBetweenTries": 5000, "credentials": { "youTubeOAuth2Api": { "id": "HE5xUScbPHMgviXV", "name": "YouTube account" } } }, output: [{}] });
const logRejected = node({ type: 'n8n-nodes-base.code', version: 2, config: { "name": "Log Row (rejected)", "parameters": { "jsCode": "// MotionLongform 탭에 남길 한 줄. STATUS는 노드마다 다르다 (uploaded / rejected).\nconst STATUS = 'rejected';\nconst p = $('Parse Longform Script').first().json;\nconst r = $('Check Render Result').first().json;\nlet url = '';\ntry { url = 'https://youtube.com/watch?v=' + $('YouTube Upload').first().json.uploadId; } catch (e) { /* 거절된 경우 */ }\nreturn [{ json: {\n  Date: $now.toFormat('yyyy-MM-dd HH:mm'), ShortTopic: p.topic, ShortVideoId: p.shortVideoId, ShortViews: p.shortViews,\n  LongTitle: p.title, Status: STATUS, LongURL: STATUS === 'uploaded' ? url : '', JobId: r.jobId\n} }];\n" } }, output: [{}] });
const appendRejected = node({ type: 'n8n-nodes-base.googleSheets', version: 4.5, config: { "name": "Append Rejected Log", "parameters": { "operation": "append", "documentId": { "__rl": true, "mode": "id", "value": "1_RFLFLkxolbaSVOw-tWf8SuBKE0FV9n6dfqUrFoOA2k" }, "sheetName": { "__rl": true, "mode": "name", "value": "MotionLongform" }, "columns": { "mappingMode": "autoMapInputData", "value": {  } }, "options": {  } }, "retryOnFail": true, "maxTries": 4, "waitBetweenTries": 5000, "credentials": { "googleSheetsOAuth2Api": { "id": "0cZFMuAKCn5sTGLr", "name": "Google Sheets account" } } }, output: [{}] });
const note = sticky("## 🎬 Motion Longform (16:9, 8~10분)\n조회수가 가장 높은 업로드 쇼츠(아직 롱폼으로 안 만든 것)를 골라 롱폼으로 확장합니다. 화·금 오후 1시.\n\nClaude 챕터 대본·장면 설계 → ElevenLabs → fal.ai 이미지(최대 14장 + 썸네일) → GitHub Actions 렌더(약 50~70분, 쇼츠와 다른 대기열) → 텔레그램 승인 → 공개 업로드 + 썸네일 + 챕터 타임스탬프 + 롱폼 재생목록\n\n기록: 시트 `MotionLongform` 탭 (거절도 기록 → 같은 쇼츠를 다시 고르지 않음. 다시 만들려면 그 줄을 지우세요)\n길이·이미지 수: Build Longform Request 맨 위", [readSheet, readLog, collect, pickShort], { color: 5 });

export default workflow('motion-longform', 'NextYou Global - Motion Longform (16:9 롱폼)')
  .add(schedule)
  .to(readSheet)
  .to(readLog)
  .to(collect)
  .to(ytStats)
  .to(pickShort)
  .to(buildReq)
  .to(claude)
  .to(parse)
  .to(tts)
  .to(music)
  .to(prepImages)
  .to(anyImages
    .onTrue(fal.to(renderJob))
    .onFalse(renderJob))
  .add(renderJob)
  .to(uploadJob)
  .to(shareJob)
  .to(startRender)
  .to(waitRender)
  .to(checkResult)
  .to(dlPreview)
  .to(uploadPreview)
  .to(tgApproval)
  .to(approved
    .onTrue(uploadMeta.to(dlFinal.to(ytUpload.to(dlThumb.to(setThumb.to(logRow.to(appendLog.to(notifyDone.to(findPlaylists.to(pickPlaylist.to(plExists
      .onTrue(addToPlaylist)
      .onFalse(createPlaylist.to(addToPlaylist)))))))))))))
    .onFalse(logRejected.to(appendRejected)))
  .add(note)
  .group('Pick a short', [readSheet, readLog, collect, ytStats, pickShort], { description: 'Most-viewed uploaded Korean short that has no long-form yet' })
  .group('Script & voice', [buildReq, claude, parse, tts, music], { description: 'Claude writes a chaptered 8-10 minute script with scene designs, ElevenLabs narration with timestamps' })
  .group('Images & render', [prepImages, anyImages, fal, renderJob, uploadJob, shareJob, startRender, waitRender, checkResult, dlPreview, uploadPreview], { description: '16:9 fal.ai images + thumbnail image, GitHub Actions renders the long composition and thumbnail' })
  .group('Publish', [tgApproval, approved, uploadMeta, dlFinal, ytUpload, dlThumb, setThumb, logRow, appendLog, notifyDone, findPlaylists, pickPlaylist, plExists, createPlaylist, addToPlaylist, logRejected, appendRejected], { description: 'Telegram approval, public upload with chapters and thumbnail, log, playlist' });

